import inspect
from wrapt import decorator
from pickle import dumps, HIGHEST_PROTOCOL
from ..call_args import get_call_args


def memoize_all(klass):
    """A wrapper for classes that applies the memoize decorator to all of its methods.

    See memoize for details."""
    targets = inspect.getmembers(klass, lambda obj: inspect.ismethod(obj) or inspect.isfunction(obj))
    for name, method in targets:
        if name not in ('__init__', '__new__'):
            setattr(klass, name, memoize(method))
    return klass


def _is_memoized(method):
    return hasattr(method, '__memoized') or (hasattr(method, '__func__') and hasattr(method.__func__, '__memoized'))


def _mark_as_memoized(method):
    try:
        setattr(method, '__memoized', True)
    except AttributeError:
        setattr(method.__func__, '__memoized', True)


def _has_mutable_arg(args):
    for value in args.values():
        if isinstance(value, (dict, list)):
            return True
    return False


def memoize(method):
    """A decorator that adds a cache for method calls.

    If the decorated method is called for the second time with the same arguments,
    the cached result will be returned immediately instead of calling the method.
    The object on which the method is called matters,
    but the method of assigning values to parameters (default value/positional/named) does not."""
    if _is_memoized(method):
        return method
    cache = {}

    @decorator
    def _memoizer(wrapped, instance, args, kwargs):
        normalized_args = get_call_args(wrapped, args, kwargs)
        if _has_mutable_arg(normalized_args):
            key = str(dumps(list(normalized_args.items()), HIGHEST_PROTOCOL)) + str(instance)
        else:
            key = frozenset(list(normalized_args.items()))
        if key not in cache:
            cache[key] = wrapped(*args, **kwargs)
        return cache[key]

    wrapped_method = _memoizer(method)  # pylint: disable=no-value-for-parameter
    _mark_as_memoized(wrapped_method)
    return wrapped_method
